void sort(int *a, int gap) {
    int swaps = 0;
    if (gap == 0) gap = 1;
    for (int i = 0; i + gap < n; i += gap) {
        if (a[i] > a[i+gap]) {
            a[i] = a[i] + a[i+gap];
            a[i+gap] = a[i] - a[i+gap];
            a[i] = a[i] - a[i+gap];
            swaps += 1;
        }
    }
    if (swaps == 0) return;
    sort(a, (int) (gap/1.3));
}

