    int gap,t,c=0;
    gap=N/shrink;
    while(gap>0)
    {
        c=0;
        if(gap<1)
        gap=1;
        for(int i=0;i<N-gap;i++)
        {
            if(arr[i]>arr[i+gap])
            {
                t=arr[i];
                arr[i]=arr[i+gap];
                arr[i+gap]=t;
                c++;
            }
        }
        if(c==0&&gap==1)
        break;
        gap=gap/shrink;
    }
    for(int i=0;i<N;i++)
    printf("%d ",arr[i]);
}
